{
  "ideas": [
    {
      "title": "Prioritize Narrative to Prevent Company‑First → Orchestration Drift",
      "description": "Develop a focused internal short report and experiment brief that (a) demonstrates why Narrative is the most recurrent first visible hierarchy shift across Experiments 007–009, (b) proposes and documents a single controlled follow‑up trial that targets Narrative (while preserving upstream inputs) and (c) provides pass/fail criteria that combine factual fidelity and editorial quality. The piece should include concrete examples from the runs (excerpted stage text), a concise explanation of why fixing Narrative matters for a company‑first introduction, and the exact experimental plan recommended in Experiment 010 (control, candidate, metrics, and evaluation checklist).",
      "audience": "Nuëyon.Compose experiment designers, prompt authors, product/content leads and reviewers who run and evaluate multi‑stage editorial pipelines.",
      "rationale": "Experiment 010’s data localizes the most recurrent first visible hierarchy shift to Narrative and recommends a targeted upstream‑boundary trial. For the team whose goal is to reliably produce company‑first introductions with Compose as a supporting product direction, a short actionable brief that makes Narrative the primary control lever is the most defensible next step. Uncertainties to surface: Narrative is the most recurrent locus but not the sole origin (Idea and Synthesis also caused drift in some runs); the planned trial must preserve other prompts to avoid confounding. The deliverable reduces noise by specifying what to hold constant, what to vary, and how to evaluate both factual and editorial outcomes.",
      "evidence": "Experiment 010 cross‑experiment patterns: “Narrative is the most recurrent first visible hierarchy shift” and per‑run localization tables showing Narrative as first in multiple Experiment 007–009 runs. The report’s implication section explicitly recommends a “one controlled upstream‑boundary trial” targeting the stage supported by the evidence (Narrative) and lists the trial design and separate evaluation buckets (factual claims, hierarchy, editorial quality)."
    },
    {
      "title": "A Two‑Gate Review: Separating Source Fidelity from Editorial Quality",
      "description": "Create a practical review framework and checklist that teams can apply at Synthesis→Narrative and Narrative→Compose handoffs. The piece would define two distinct gates (1) source/factual fidelity and (2) editorial quality/hook/readability, provide concrete pass/fail tests and example failure modes drawn from the experiments, and recommend tooling/logging to make gate decisions reproducible.",
      "audience": "Reviewers, content QA engineers, and experiment evaluators responsible for final acceptance of generated company introductions.",
      "rationale": "Experiment 010 finds that factual support and editorial framing are distinct failure modes—an output can be source‑aligned yet editorially the wrong lead, or vice versa. A clear two‑gate process reduces both false positives (factually true but wrong editorial lead) and false negatives (engaging prose that invents unsupported claims). Uncertainty: the report notes inconsistent measurement of engagement metrics; this framework would need to define replicable editorial scoring criteria.",
      "evidence": "Executive findings: “Factual and editorial failures are distinct.” Cross‑experiment patterns: “Source fidelity and editorial quality need separate gates.” Experiment 010 recommends separately evaluating factual claims, company‑first story hierarchy, and editorial quality."
    },
    {
      "title": "Close the Upstream Format Leakage: Audit and Prompt Boundary Checklist",
      "description": "Produce an actionable checklist and small refactor plan to remove explicit format references from Idea/Research/Narrative system/user prompts where they contradict the Master Workflow’s format‑independence rule. Include a short test suite that flags any prompt text containing platform-specific words (LinkedIn, Article, post, etc.), and a lightweight before/after experiment that shows whether removing format priming reduces format‑related deviations.",
      "audience": "Prompt engineers, system prompt owners, and workflow architects responsible for the Master Workflow and upstream agent prompts.",
      "rationale": "Experiment 010 documents upstream prompt snapshots that contain format references contrary to the architecture rule and identifies this as a plausible source of priming. A scoped audit and remediation reduces a plausible confound for downstream narrative/style drift. Uncertainty: report explicitly states format references do not prove causation for orchestration drift; the checklist should therefore be applied as a controlled intervention and measured.",
      "evidence": "Format‑agnostic architecture audit: examples where Idea/Research/Narrative frozen prompts include 'supported output formats' and explicit references to Article/LinkedIn compatibility. Interpretation section: labels this an 'instruction‑boundary inconsistency' and a 'plausible source of format priming.'"
    },
    {
      "title": "Experiment Template: Controlled Upstream‑Boundary Trial for Hierarchy Preservation",
      "description": "Draft a runnable experiment template (manifest plus evaluation rubrics) that implements Experiment 010’s five recommended controls: hold reconstructed source and execution settings identical, target Narrative (compare its input Synthesis), remove or retain format priming per hypothesis, run repeated full‑pipeline trials, and evaluate three axes (factuality, hierarchy, editorial quality). Include example command lines, artifact paths, and the evidence‑manifest tracking required for reproducibility.",
      "audience": "Experiment operators, data-science/product teams running Compose experiments who need a reproducible trial setup.",
      "rationale": "Experiment 010 contains a clear experimental design recommendation but not a canned manifest. Packaging it into an executable template will accelerate validation and make results comparable. Uncertainties: specific pass thresholds for editorial quality remain to be defined; the template should allow configuration of those thresholds.",
      "evidence": "Implication for the next focused trial section: five numbered points prescribing target stage, rule to test, format‑priming handling, repeated runs with interleaving, and separate evaluation axes. Repository paths and evidence‑manifest note ensure reproducibility guidance exists."
    },
    {
      "title": "How Compose Amplifies Upstream Frames — A Short Diagnostic Note",
      "description": "Write a concise analytic note illustrating with run excerpts how Compose either inherits, amplifies, or strengthens upstream frames into stronger factual or editorial claims. The note will categorize amplification modes (inherit, amplify, add strength/certainty, invent audience) and show representative stage transitions from the source runs.",
      "audience": "Product managers and senior reviewers who need a quick mental model of where amplification happens and what to watch for.",
      "rationale": "Experiment 010 shows Compose can inherit or amplify upstream choices—sometimes adding unverifiable certainty or broader audiences. A short taxonomy helps decision‑makers know whether a Compose‑side fix is sufficient or whether upstream stages must be changed. Uncertainty: amplification patterns vary by run and are not deterministic; the note should emphasize observed examples, not causal claims.",
      "evidence": "Cross‑experiment observations: 'Compose can amplify, add factual strength, or simply inherit' with examples such as 'orchestration‑first', 'reliably converts', 'predictable and repeatable', and per‑run tables demonstrating when Compose escalated phrasing."
    }
  ]
